/*
 * A383671  The limiting word that starts with 0, as a sequence, generated by
 *          s(0) = 0, s(1) = 12, s(n) = concatenation of s(n - 2) and s(n -
 *          1).
 * https://oeis.org/A383671
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn
 * Formula:   not stated
 * Range:     u8 n <= 85, u16 n <= 85, u32 n <= 85, u64 n <= 85, u128 n <= 85,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Computes the nth term of OEIS A383671.
   The word is generated by s(0)=0, s(1)=12, s(n)=s(n‑2) s(n‑1).
   The emitted sequence is the subsequence s(2k) (k≥0). */

seq_t a(idx_t n)
{
    /* Pre‑compute the lengths |s(i)| until we exceed n. */
    idx_t len[256];
    len[0] = 1;                       /* |s(0)| */
    len[1] = 2;                       /* |s(1)| */
    idx_t count = 2;                  /* next free index in len[] */

    while (len[count-1] <= n) {
        if (count >= 255)              /* safety guard */
            break;
        len[count] = len[count-2] + len[count-1];
        ++count;
    }

    /* Use the smallest even index whose length exceeds n. */
    idx_t i = count-1;
    if (i & 1u) {                    /* i is odd, move to the next element */
        /* We know len[count] does not yet exist but count <= 254 here. */
        len[count] = len[count-2] + len[count-1];
        ++count;
        ++i;
    }

    /* Walk the recursive definition until reaching s(0) or s(1). */
    idx_t pos = n;
    while (1) {
        if (i == 0u) {
            return (seq_t)0;
        }
        if (i == 1u) {
            return (pos == 0u) ? (seq_t)1 : (seq_t)2;
        }
        /* i >= 2 */
        if (pos < len[i-2]) {
            i -= 2;                  /* descend into left part */
        } else {
            pos -= len[i-2];
            i -= 1;                  /* descend into right part */
        }
    }
}
